contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address spender, uint256 approveAmt, uint256 amount) public payable {
        require(approveAmt >= amount);
        // fund this contract with shares by minting via buyShares (totalSupply == 0 path)
        require(amount > 3004, "need shares");
        c.approve(spender, approveAmt); if (__ESBMC_reverted()) return;
        uint256 allowBefore = c.allowance(address(this), spender); if (__ESBMC_reverted()) return;
        // make a first transferFrom for (amount - 2000) to reach a nonzero transferable balance state
        c.transferFrom(address(this), spender, amount - 2000); if (__ESBMC_reverted()) return;
        uint256 allowMid = c.allowance(address(this), spender); if (__ESBMC_reverted()) return;
        uint256 balSpenderBefore = c.balanceOf(spender); if (__ESBMC_reverted()) return;
        bool ok = c.transferFrom(address(this), spender, 2000); if (__ESBMC_reverted()) return;
        uint256 allowAfter = c.allowance(address(this), spender); if (__ESBMC_reverted()) return;
        uint256 balSpenderAfter = c.balanceOf(spender); if (__ESBMC_reverted()) return;
        assert(ok && allowBefore == approveAmt && allowMid == approveAmt - (amount - 2000) && allowAfter == allowMid - 2000 && balSpenderAfter == balSpenderBefore + 2000);
    }
    receive() external payable {}
}

