    GSPFunding c;

    function setUp() public {
        c = new GSPFunding();
    }

    function _run(address spender, uint256 approveAmt, uint256 amount) internal {
        vm.assume(approveAmt >= amount);
        vm.assume(amount > 3004);
        try c.approve(spender, approveAmt) {} catch { return; }
        uint256 allowBefore;
        try c.allowance(address(this), spender) returns (uint256 __r) { allowBefore = __r; } catch { return; }
        try c.transferFrom(address(this), spender, amount - 2000) {} catch { return; }
        uint256 allowMid;
        try c.allowance(address(this), spender) returns (uint256 __r) { allowMid = __r; } catch { return; }
        uint256 balSpenderBefore;
        try c.balanceOf(spender) returns (uint256 __r) { balSpenderBefore = __r; } catch { return; }
        bool ok;
        try c.transferFrom(address(this), spender, 2000) returns (bool __r) { ok = __r; } catch { return; }
